CREATE TABLE public.orders(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),clerk_user_id TEXT,customer_name TEXT NOT NULL,customer_email TEXT NOT NULL,customer_phone TEXT NOT NULL,delivery_address TEXT NOT NULL,delivery_municipality TEXT NOT NULL,total_amount INTEGER NOT NULL,status TEXT NOT NULL,payment_method TEXT NOT NULL,notes TEXT);CREATE TABLE public.order_items(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),order_id UUID NOT NULL REFERENCES public.orders(id) ON DELETE CASCADE,product_id TEXT NOT NULL,product_name TEXT NOT NULL,quantity INTEGER NOT NULL,price_at_purchase INTEGER NOT NULL);CREATE TABLE public.fixture_fault(enabled BOOLEAN NOT NULL);INSERT INTO public.fixture_fault VALUES(false);CREATE FUNCTION public.inject_item_failure() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF (SELECT enabled FROM public.fixture_fault) THEN RAISE EXCEPTION 'INJECTED_ITEM_FAILURE'; END IF;RETURN NEW;END $$;CREATE TRIGGER fixture_fail_items BEFORE INSERT ON public.order_items FOR EACH ROW EXECUTE FUNCTION public.inject_item_failure();
